def prod_signs(arr):
    if not arr:
        return None

    total_magnitude = sum(abs(x) for x in arr)
    product_sign = 1

    for x in arr:
        if x > 0:
            product_sign *= 1
        elif x < 0:
            product_sign *= -1
        else:
            return 0

    return total_magnitude * product_sign

